// ---- the descriptor + the ONE export ----
// A mutable copy of the constexpr descriptor for reco_abnormal: the DLL is the only
// place that can fill `mappings`/`mapping_count`, because PPCFuncMappings is ITS
// symbol.  Everything else is inherited verbatim from host/futari_module_desc.h.
static FutariModuleDesc g_desc;

extern "C" __declspec(dllexport)
const FutariModuleDesc* FutariModuleBind(const FutariHostAbi* h) {
    if (!h) return nullptr;
    if (h->abi_version != FUTARI_HOST_ABI_VERSION) return nullptr;
    if (h->struct_size != (uint32_t)sizeof(FutariHostAbi)) return nullptr;
    if (h->abi_hash    != FUTARI_HOST_ABI_HASH) return nullptr;
    g_host = h;
    futari_p_import_calls = h->pg_import_calls;
    futari_p_rt_startline = h->pg_rt_startline;
    futari_p_rt_realstage = h->pg_rt_realstage;
    futari_p_rt_romactive = h->pg_rt_romactive;
    g_desc = *futari_desc();          // the compile-time descriptor for this module
    uint32_t n = 0;
    for (const PPCFuncMapping* m = PPCFuncMappings; m->guest || m->host; ++m) ++n;
    g_desc.mappings      = PPCFuncMappings;
    g_desc.mapping_count = n;
    return &g_desc;
}
